const API='https://api.besma.co.kr',token=localStorage.getItem('besma_token'),el=id=>document.getElementById(id),make=(tag,text)=>{const e=document.createElement(tag);if(text!=null)e.textContent=text;return e;};
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,valid=s=>typeof s==='string'&&/^20\d\d-\d\d-\d\d$/.test(s)&&!isNaN(Date.parse(s));
let month=new Date(),items=[],user=null,sequence=0,reader=false;month=new Date(month.getFullYear(),month.getMonth(),1);el('mine').checked=new URLSearchParams(location.search).get('mine')==='1';
const current=()=>token&&localStorage.getItem('besma_token')===token;
async function get(path){const r=await fetch(API+path,{headers:{Authorization:'Bearer '+token},cache:'no-store',credentials:'omit',redirect:'error',signal:AbortSignal.timeout(15000)});if(!current())throw Error('로그인 계정이 변경되었습니다.');if(!r.ok){const e=Error(r.status===401?'로그인 후 확인하세요.':r.status===403?'캘린더 조회 권한이 없습니다.':'일정을 불러오지 못했습니다. 새로고침해 주세요.');e.status=r.status;throw e;}return r.json();}
function selectDay(day){el('day-title').textContent=day+' 일정';el('day-items').replaceChildren();const rows=items.filter(x=>x.scheduled_date<=day&&(x.due_date||x.scheduled_date)>=day&&(!el('mine').checked||x.owner_user_id===user.id));for(const item of rows){const box=make('article');box.className='detail-item';box.append(make('strong',item.title),make('p',item.scheduled_date+(item.due_date&&item.due_date!==item.scheduled_date?' ~ '+item.due_date+' · 기간 일정':'')),make('p',({PLANNED:'예정',IN_PROGRESS:'진행 중',ON_HOLD:'보류',COMPLETED:'완료'})[item.status]||'확인 필요'));if(item.source==='INSPECTION_PLAN'){const a=make('a','평가·점검 내용 보기');a.href=(reader?'/half-year-reader.html':'/inspection-plan.html')+'?plan='+encodeURIComponent(item.public_id);box.append(a);}el('day-items').append(box);}if(!rows.length)el('day-items').append(make('p','등록된 일정이 없습니다.'));}
export function weekSegments(rows,start,end){const lanes=[];for(const item of rows.filter(x=>x.due_date&&x.due_date>x.scheduled_date&&x.scheduled_date<=end&&x.due_date>=start).sort((a,b)=>a.scheduled_date.localeCompare(b.scheduled_date)||a.public_id.localeCompare(b.public_id)))lanes.push(item);return lanes;}
function draw(){el('month').textContent=`${month.getFullYear()}년 ${month.getMonth()+1}월`;const start=new Date(month);start.setDate(start.getDate()-start.getDay());const grid=el('calendar');grid.replaceChildren();const rows=items.filter(x=>!el('mine').checked||x.owner_user_id===user.id);for(let w=0;w<6;w++){const ws=new Date(start);ws.setDate(start.getDate()+w*7);const we=new Date(ws);we.setDate(ws.getDate()+6);const lanes=weekSegments(rows,iso(ws),iso(we));for(let j=0;j<7;j++){const date=new Date(ws);date.setDate(ws.getDate()+j);const day=iso(date),cell=make('div');cell.className='day'+(date.getMonth()!==month.getMonth()?' outside':'')+(j===0?' sunday':j===6?' saturday':'')+(day===iso(new Date())?' today':'');const b=make('button',date.getDate());b.type='button';b.className='date';b.setAttribute('aria-label',day+' 일정 보기');b.onclick=()=>{selectDay(day);el('details').focus({preventScroll:true});};cell.append(b);for(const item of lanes){const active=item.scheduled_date<=day&&item.due_date>=day,p=make('button');p.type='button';p.className='period'+(!active?' empty':'')+(item.status==='COMPLETED'?' completed':'');p.title=item.title+' · '+item.scheduled_date+' ~ '+item.due_date+' · 기간 일정';p.setAttribute('aria-label',p.title);if(!active){p.tabIndex=-1;p.disabled=true;}if(active&&(j===0||day===item.scheduled_date))p.append(make('span','기간 일정 · '+item.title));p.onclick=()=>selectDay(day);cell.append(p);}for(const item of rows.filter(x=>x.scheduled_date===day&&(!x.due_date||x.due_date===x.scheduled_date))){const p=make('button',item.title.replace(/^\[점검\]\s*/,''));p.type='button';p.className='event'+(item.status==='COMPLETED'?' completed':'');p.title=item.title;p.onclick=()=>selectDay(day);cell.append(p);}grid.append(cell);}}}
async function load(){const run=++sequence;items=[];draw();el('day-items').replaceChildren();el('day-title').textContent='날짜를 선택하세요.';if(!token){el('status').textContent='로그인 후 캘린더를 확인할 수 있습니다.';const a=make('a','로그인');a.href='/login?form=1';el('status').append(' ',a);return;}el('status').textContent='일정 확인 중';try{user=await get('/auth/me');const first=new Date(month);first.setDate(first.getDate()-first.getDay());const last=new Date(first);last.setDate(first.getDate()+41);const query=new URLSearchParams({from_date:iso(first),to_date:iso(last)});let result;try{result=await get('/safety-features/team-schedule/items?'+query);}catch(e){if(e.status!==403)throw e;result=await get('/safety-features/half-year-reader/calendar?'+query);reader=true;}if(run!==sequence||!current())return;if(!Array.isArray(result.items)||result.items.length>2000||result.items.some(x=>!valid(x.scheduled_date)||x.due_date&&(!valid(x.due_date)||x.due_date<x.scheduled_date)||typeof x.title!=='string'||!/^[-a-zA-Z0-9_]{8,100}$/.test(x.public_id)))throw Error('일정의 날짜와 조회 범위를 확인해 주세요.');items=result.items;el('status').textContent='업무툴 일정 동기화 · '+items.length+'건'+(reader?' · 조회 전용':'');draw();}catch(e){if(run===sequence&&current()){items=[];draw();el('status').textContent=e.message;}}}
el('previous').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1);load();};el('next').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1);load();};el('today').onclick=()=>{const d=new Date();month=new Date(d.getFullYear(),d.getMonth(),1);load();};el('refresh').onclick=load;el('mine').onchange=()=>{draw();el('day-items').replaceChildren();};addEventListener('storage',e=>{if(e.key==='besma_token'||e.key===null){sequence++;items=[];draw();el('day-items').replaceChildren();el('status').textContent='로그인 계정이 변경되었습니다. 화면을 다시 열어 주세요.';}});load();
